import { FC, useState } from 'react';

import { Button, Flex, Input } from 'antd';

import { useBrand } from 'entities/Brand/hooks/useBrand';
import { MOCK_COLLECTIONS } from 'shared/consts/MOCK_FOR_CATALOG';

import styles from './CreateAutomationForm.module.scss';

interface ICreateAutomationFormProps {
	handleCancelClick?: () => void;
}

export const CreateAutomationForm: FC<ICreateAutomationFormProps> = ({ handleCancelClick }) => {
	const { t, createNewAutomation, saveToAutomation } = useBrand();
	const [automationName, setAutomationName] = useState<string>('');

	const handleCreateAutomationClick = () => {
		createNewAutomation(automationName);
		saveToAutomation(automationName);
	};

	const handleAutomationClick = (value: string) => {
		setAutomationName(value);
	};

	return (
		<Flex gap={16} vertical>
			<Flex gap={8}>
				<Input
					placeholder={t('Имя автоматизации')}
					size="large"
					value={automationName}
					onChange={(e) => setAutomationName(e.target.value)}
				/>
			</Flex>
			<Flex gap={4} className={styles.createAutomationForm__ovx}>
				{/*TODO: get from api*/}
				{MOCK_COLLECTIONS.map((automation) => (
					<Button
						key={automation.id}
						size="small"
						shape="round"
						htmlType="button"
						onClick={() => handleAutomationClick(automation.name)}>
						{automation.name}
					</Button>
				))}
			</Flex>
			{!!handleCancelClick && (
				<Flex justify="space-between" gap={12}>
					<Button onClick={handleCancelClick} size="large">
						{t('Отменить')}
					</Button>
					<Button onClick={handleCreateAutomationClick} type="primary" size="large" disabled={!automationName}>
						{t('Создать автоматизацию')}
					</Button>
				</Flex>
			)}
		</Flex>
	);
};
