import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Tag, Typography } from 'antd';
import cn from 'classnames';

import { type BrandRead, EPaymentModel } from 'entities/Brand';

import { EPaymentModelMap } from '../../model/types';

import styles from './BrandDetails.module.scss';

interface IBrandDetailsProps extends HTMLAttributes<HTMLDListElement> {
	brand: BrandRead;
}

export const BrandDetails: FC<IBrandDetailsProps> = ({ className, brand, ...props }) => {
	const { t } = useTranslation();

	return (
		<dl {...props} className={cn(className, styles.brandDetails)}>
			<div className={styles.brandDetails__line}>
				<dt>
					<Typography.Text type={'secondary'}>{t('Модель оплаты')}:</Typography.Text>
				</dt>
				<dd>
					<Tag color={EPaymentModelMap[EPaymentModel.CPA].color} bordered={false}>
						{EPaymentModelMap[EPaymentModel.CPA].text}
					</Tag>
				</dd>
			</div>
			<div className={styles.brandDetails__line}>
				<dt>
					<Typography.Text type={'secondary'}>{t('Ставка')}:</Typography.Text>
				</dt>
				<dd>
					{Object.values(brand.grouped_rates)
						.filter((rate) => !!rate)
						.join(', ')}
				</dd>
			</div>
		</dl>
	);
};
