import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Drawer, DrawerProps } from 'antd';
import cn from 'classnames';

import { CreateAutomationForm } from 'entities/Automation/ui/CreateAutomationForm/CreateAutomationForm';
import { useBrandSlice } from 'entities/Brand';

import styles from './CreateAutomationDrawer.module.scss';

interface ICreateAutomationDrawerProps extends DrawerProps {}

export const CreateAutomationDrawer: FC<ICreateAutomationDrawerProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { setIsOpenCreateAutomationDrawer, isOpenCreateAutomationDrawer } = useBrandSlice();

	return (
		<Drawer
			title={t('Создать автоматизацию и сохранить в неё пост')}
			open={isOpenCreateAutomationDrawer}
			onClose={() => setIsOpenCreateAutomationDrawer(false)}
			placement="bottom"
			destroyOnHidden
			{...props}
			className={cn(className, styles.createAutomationDrawer)}>
			<CreateAutomationForm handleCancelClick={() => setIsOpenCreateAutomationDrawer(false)} />
		</Drawer>
	);
};
